org.apache.http.impl.client.DefaultHttpClient.addResponseInterceptor(new HttpResponseInterceptor() {
            @Override
            public void process(HttpResponse response, HttpContext context) throws HttpException, IOException {
                if (response.containsHeader("Location")) {
                    Header[] locations = response.getHeaders("Location");
                    if (locations.length > 0) {
                        URL location = new URL(locations[0].getValue());
                        context.setAttribute(LAST_REDIRECT_URL, location);
                    }
                }
            }
        })

org.apache.http.impl.client.DefaultHttpClient.addRequestInterceptor(new HttpRequestInterceptor()
		{
			public void process(final HttpRequest r, final HttpContext context) throws HttpException, IOException
			{
				assertNotNull(r.getHeaders(HttpHeaders.AUTHORIZATION));
				assertEquals(1, r.getHeaders(HttpHeaders.AUTHORIZATION).length);
				client.removeRequestInterceptorByClass(this.getClass());
			}
		})

