org.smartboot.mqtt.common.InflightQueue.offer(publishBuilder, offset -> {
            consumer.accept(publishBuilder.getPacketId());
            //最早发送的消息若收到响应，则更新点位
            if (offset != -1) {
                synchronized (MqttClient.this) {
                    MqttClient.this.notifyAll();
                }
            }
        }, 1)

