org.smartboot.mqtt.common.InflightQueue.put(publishBuilder, (message) -> {
                consumer.accept(message.getVariableHeader().getPacketId());
                //最早发送的消息若收到响应，则更新点位
                synchronized (MqttClient.this) {
                    MqttClient.this.notifyAll();
                }
            })

