org.apache.solr.client.solrj.impl.HttpClientUtil.setSchemaRegistryProvider(new HttpClientUtil.SchemaRegistryProvider() {
                @Override
                public Registry<ConnectionSocketFactory> getSchemaRegistry() {
                    RegistryBuilder<ConnectionSocketFactory> builder = RegistryBuilder.create();
                    builder.register("http", PlainConnectionSocketFactory.getSocketFactory());
                    builder.register("https", sslSocketFactory);
                    return builder.build();
                }
            })

